const cmds = [
  ["agents", "sed -n '1,280p' AGENTS.md", 30000],
  ["candidate", "nl -ba candidates/bge_finetune_probe.py | sed -n '1,360p'", 30000],
  ["overview", "sed -n '1,300p' official/OVERVIEW.md", 30000],
  ["submission", "sed -n '1,320p' official/SUBMISSION.md", 30000],
  ["solution", "nl -ba input/competition/solution.py | sed -n '1,360p'", 30000],
  ["readme", "sed -n '1,300p' input/competition/README.md", 30000],
  ["metadata", "wc -l input/competition/dataset/{train,dev,test_public}/*.jsonl input/competition/sample_submission.csv; du -sh input/competition/models/bge-base-en-v1.5 input/competition; sed -n '1,5p' input/competition/dataset/train/data.jsonl; sed -n '1,5p' input/competition/dataset/train/answers.jsonl; sed -n '1,5p' input/competition/dataset/dev/data.jsonl; sed -n '1,5p' input/competition/dataset/dev/answers.jsonl; sed -n '1,5p' input/competition/sample_submission.csv", 30000]
];
const out = await Promise.all(cmds.map(async ([name, cmd, max]) => {
  const r = await tools.exec_command({cmd, workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project", yield_time_ms:10000, max_output_tokens:max});
  return `===== ${name} =====\n${r.output}`;
}));
out.forEach(text);

const out = await Promise.all([
  tools.exec_command({cmd:"nl -ba candidates/bge_finetune_probe.py | sed -n '1,300p'",workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project",yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"sed -n '1,280p' official/OVERVIEW.md",workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project",yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"sed -n '1,320p' official/SUBMISSION.md",workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project",yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"nl -ba input/competition/solution.py | sed -n '1,300p'",workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project",yield_time_ms:10000,max_output_tokens:30000})
]);
for (let i=0;i<out.length;i++) { text(["CANDIDATE","OVERVIEW","SUBMISSION","SOLUTION"][i]+"\n"+out[i].output); }

const r = await tools.exec_command({"cmd":"nl -ba candidates/bge_finetune_probe.py | sed -n '285,430p'; python - <<'PY'
import json,re,statistics, pathlib
root=pathlib.Path('input/competition/dataset')
pat=re.compile(r'(?<=[.!?])[\"\']?\s+')
for split in ['train','dev','test_public']:
 rows=[json.loads(x) for x in (root/split/'data.jsonl').read_text().splitlines() if x.strip()]
 counts=[]; lens=[]
 aligned=None
 if (root/split/'answers.jsonl').exists():
  ans={r['id']:int(r['boundary_char_index']) for r in map(json.loads,(root/split/'answers.jsonl').read_text().splitlines())}
  aligned=sum(ans[r['id']] in ([0]+[m.end() for m in pat.finditer(r['text'])]) for r in rows)
 for row in rows:
  starts=[0]+[m.end() for m in pat.finditer(row['text'])]
  counts.append(len(starts)); lens.append(len(row['text']))
 print(split,len(rows),'sentences',min(counts),statistics.mean(counts),max(counts),'chars',min(lens),statistics.mean(lens),max(lens),'aligned',aligned)
PY","workdir":"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project","yield_time_ms":10000,"max_output_tokens":20000});
text(r.output);

const cmds = [
  ["versions", "python - <<'PY'\nimport sys,torch,transformers\nprint(sys.version)\nprint('torch',torch.__version__,'transformers',transformers.__version__,'cuda',torch.cuda.is_available(),torch.cuda.device_count())\nfor i in range(torch.cuda.device_count()):\n print(i,torch.cuda.get_device_name(i),tuple(x/2**30 for x in torch.cuda.mem_get_info(i)))\nPY"],
  ["tree", "find . -maxdepth 3 -type f | sort | sed -n '1,240p'"],
  ["references", "rg -n \"bge_finetune|OriginModel|emission =|AutoModel|GradScaler|submission.csv\" candidates submission . -g '*.py' -g '*.md' -g '*.jsonl' -g 'kernel-metadata.json'"],
  ["modelconfig", "sed -n '1,220p' input/competition/models/bge-base-en-v1.5/config.json; sed -n '1,220p' input/competition/models/bge-base-en-v1.5/tokenizer_config.json"],
  ["resource", "nproc; free -h; nvidia-smi --query-gpu=index,name,memory.total,memory.free,utilization.gpu --format=csv,noheader"]
];
const out=await Promise.all(cmds.map(async ([name,cmd])=>{const r=await tools.exec_command({cmd,workdir:"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project",yield_time_ms:10000,max_output_tokens:30000});return `==== ${name} ====\n${r.output}`;}));
out.forEach(text);

const r = await tools.exec_command({"cmd":"python candidates/bge_finetune_probe.py","workdir":"/workspace/IOAI/ioai-competition-runs/ioai-2026-task-5-westlake-nlp-24/project","yield_time_ms":1000,"max_output_tokens":20000});
text(r.output);
if (r.session_id) text(`SESSION_ID=${r.session_id}`);

