const r = await tools.exec_command({"cmd":"python - <<'PY'
import json,re,pathlib,collections,numpy as np
root=pathlib.Path('input/competition/dataset'); pat=re.compile(r'(?<=[.!?])[\"\']?\s+')
for sp in ['train','dev']:
 rows=[json.loads(x) for x in (root/sp/'data.jsonl').read_text().splitlines()]
 truth={x['id']:int(x['boundary_char_index']) for x in map(json.loads,(root/sp/'answers.jsonl').read_text().splitlines())}
 excl=[]; align=[]
 for r in rows:
  starts=[0]+[m.end() for m in pat.finditer(r['text'])]
  b=truth[r['id']]; align.append(b in starts)
  valid=[i for i in range(1,len(starts)) if len(r['text'][:starts[i]].split())>=180 and len(r['text'][starts[i]:].split())>=180]
  if starts.index(b) not in (valid if valid else list(range(1,len(starts)))):
   excl.append((r['id'],len(r['text'][:b].split()),len(r['text'][b:].split()),len(valid)))
 print(sp,'aligned',sum(align),'/',len(rows),'valid truth',len(rows)-len(excl),'excluded',excl[:10])
PY
python -m py_compile candidates/bge_finetune_probe.py
wc -c candidates/bge_finetune_probe.py submission/script.py
